      "value": -112.6274,
      "unit": "basis_points",
      "evidence": ["a03:s02", "a03:s03", "a03:s06"],
      "sql": "SELECT ((SELECT amount FROM financials WHERE period_end = '2024-12-31' AND months = 3 AND measure = 'Operating income') / (SELECT amount FROM financials WHERE period_end = '2024-12-31' AND months = 3 AND measure = 'Total revenue') - ((SELECT amount FROM financials WHERE period_end = '2024-12-31' AND months = 6 AND measure = 'Operating income') - (SELECT amount FROM financials WHERE period_end = '2024-12-31' AND months = 3 AND measure = 'Operating income')) / ((SELECT amount FROM financials WHERE period_end = '2024-12-31' AND months = 6 AND measure = 'Total revenue') - (SELECT amount FROM financials WHERE period_end = '2024-12-31' AND months = 3 AND measure = 'Total revenue'))) * 10000;"
    },
    {
      "id": "azure_gap",
      "status": "answered",
      "value": -1.0,
      "unit": "percentage_points",
      "evidence": ["a03:s01", "a03:s04"],
      "sql": "SELECT (SELECT constant_currency_percent FROM growth WHERE business = 'Azure and other cloud services') - (SELECT high FROM guidance WHERE business = 'Azure and other cloud services' AND fiscal_period = 'Q2FY2025' AND issue_date = '2024-10-30');"
    }
  ],
  "conclusion": {
    "verdict": "contradicted",
    "evidence": ["a03:s01", "a03:s04"]
  }
}
EOF

